import {
  observeOverlaySize,
  observeAnimationDone,
} from '../utils/popper-modifiers.js';

// #region Typings
/** Accepted properties for FeatureHighlight */
export type FeatureHighlightPlacement =
  | 'left-top'
  | 'left-middle'
  | 'left-bottom'
  | 'right-top'
  | 'right-middle'
  | 'right-bottom'
  | 'top-left'
  | 'top-middle'
  | 'top-right'
  | 'bottom-left'
  | 'bottom-middle'
  | 'bottom-right';

export interface FeatureHighlightProps extends WithChildren, AriaLabelingProps {
  /**
   * Whether the FeatureHighlight is currently shown or not. Has to be controlled by the consumer.
   */
  open: boolean;
  /**
   * The element the popover is referring to (i.e. where the pointer is pointing to).
   */
  anchor: HTMLElement | null;
  /**
   * Placement of the FeatureHighlight.
   * @defaultValue 'right-bottom'
   */
  placement?: FeatureHighlightPlacement;
  /**
   * Callback fired when closing the FeatureHighlight.
   */
  onClose: () => void;
}

type FeatureHighlightSlots = {
  title: React.ReactElement | null;
  visual: React.ReactElement | null;
  content: React.ReactElement | null;
  actions: React.ReactElement | null;
};
// #endregion Typings

